package com.lingualearn.app.data.content

/**
 * German (de) and Italian (it) comprehensive curriculum content.
 * 10 levels × 6 topics = 60 distinct lessons per language.
 */
object GermanCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Guten Morgen / Guten Abend", "Good morning / Good evening", "GOO-ten MOR-gen / GOO-ten AH-bent", "Guten Morgen, wie geht es dir?", "Good morning, how are you?", "German capitalizes every single noun.")
                "Introducing Yourself" -> CurriculumLessonContent("Ich heiße...", "My name is...", "ikh HY-seh", "Ich heiße Lukas und komme aus Berlin.", "My name is Lukas and I come from Berlin.", "'heißen' is used for names, while 'sein' means 'to be'.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Ja / Nein / Bitte / Danke", "Yes / No / Please / Thank you", "yah / nyn / BIT-teh / DAHN-keh", "Ja, bitte! Vielen Dank für die Hilfe.", "Yes, please! Many thanks for the help.", "'Bitte' can mean please, you're welcome, or pardon.")
                "Numbers 1–10" -> CurriculumLessonContent("Eins, zwei, drei...", "1 to 10 numerals", "eyns, tsvy, dry", "Ich hätte gern zwei Brötchen, bitte.", "I would like two bread rolls, please.", "Numbers 1-10 form the foundation for shopping and counting.")
                "Basic Pronouns" -> CurriculumLessonContent("Ich, du, er, sie, wir, ihr, Sie", "I, you, he, she, we, y'all, You (formal)", "ikh, doo, ayr, zee, veer, eer, Zee", "Wir lernen heute zusammen Deutsch.", "We are learning German together today.", "'Sie' with a capital S is the formal 'you'.")
                else -> CurriculumLessonContent("Entschuldigung und Auf Wiedersehen", "Excuse me and Goodbye", "ent-SHOOL-dee-goong / owf VEE-der-zayn", "Entschuldigung, wo ist der Bahnhof?", "Excuse me, where is the train station?", "'Auf Wiedersehen' literally means 'until we see again'.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("Die Familie", "The family", "dee fah-MEE-lyeh", "Meine Schwester und mein Bruder studieren hier.", "My sister and my brother study here.", "Masculine nouns take 'mein', feminine take 'meine'.")
                "Colors" -> CurriculumLessonContent("Rot, Blau, Gelb, Grün", "Red, Blue, Yellow, Green", "roht, blow, gelp, groon", "Das rote Auto gehört meinem Vater.", "The red car belongs to my father.", "Adjective endings change depending on gender and case.")
                "Food" -> CurriculumLessonContent("Das Frühstück und das Brot", "Breakfast and bread", "dahs FROO-shtook / dahs broht", "Zum Frühstück esse ich Müsli mit frischem Obst.", "For breakfast I eat muesli with fresh fruit.", "Germany is famous for over 3,000 types of bread.")
                "Days & Months" -> CurriculumLessonContent("Montag bis Sonntag", "Monday to Sunday", "MOHN-tahk bis ZOHN-tahk", "Am Samstag gehen wir in den Park.", "On Saturday we are going to the park.", "Use 'am' (an dem) with days of the week.")
                "Simple Questions" -> CurriculumLessonContent("Wer? Was? Wo? Warum?", "Who? What? Where? Why?", "vayr, vahs, voh, vah-ROOM", "Warum lernst du die deutsche Sprache?", "Why are you learning the German language?", "In German questions, the verb takes the second position.")
                else -> CurriculumLessonContent("Haben und Sein", "To have and To be", "HAH-ben / zyn", "Ich bin müde, aber ich habe Zeit.", "I am tired, but I have time.", "The two most essential auxiliary verbs in German.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("Aufstehen und Zähneputzen", "Waking up and brushing teeth", "OWF-shtay-en", "Unter der Woche stehe ich um sechs Uhr auf.", "During the week I get up at six o'clock.", "'Aufstehen' is a separable verb: 'stehe ... auf'.")
                "Shopping" -> CurriculumLessonContent("Was kostet das?", "How much does that cost?", "vahs KOS-tet dahs", "Entschuldigung, was kostet dieser Pullover?", "Excuse me, how much does this sweater cost?", "'Kostet' changes to 'kosten' for plural items.")
                "Time" -> CurriculumLessonContent("Wie spät ist es?", "What time is it?", "vee shpayt ist es", "Es ist Viertel nach drei am Nachmittag.", "It is a quarter past three in the afternoon.", "'Viertel vor' means quarter to, 'halb' means half to.")
                "Directions" -> CurriculumLessonContent("Geradeaus und nach rechts", "Straight ahead and to the right", "geh-RAH-deh-ows / nakh rekhts", "Gehen Sie geradeaus und biegen Sie links ab.", "Go straight ahead and turn left.", "'Links' is left, 'rechts' is right.")
                "Simple Sentences" -> CurriculumLessonContent("Ich möchte einen Kaffee trinken", "I would like to drink a coffee", "ikh MOEKH-teh", "Ich möchte einen heißen Kaffee mit Milch trinken.", "I would like to drink a hot coffee with milk.", "'Möchte' pairs with the infinitive at the end of the sentence.")
                else -> CurriculumLessonContent("Wie geht's dir?", "How's it going with you? (informal)", "vee gayts deer", "Mir geht es gut, danke! Und dir?", "I'm doing well, thanks! And you?", "'Wie geht's' is short for 'Wie geht es'.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Gestern habe ich ein Buch gelesen", "Yesterday I read a book", "GES-tern HAH-beh ikh", "Gestern habe ich meine Großeltern besucht.", "Yesterday I visited my grandparents.", "The conversational past (Perfekt) uses haben/sein + Partizip II.")
                "Future Plans" -> CurriculumLessonContent("Ich werde nächsten Sommer reisen", "I will travel next summer", "ikh VEHR-deh", "Nächstes Jahr werde ich in Wien studieren.", "Next year I will study in Vienna.", "Futur I is formed with 'werden' + infinitive.")
                "Travel" -> CurriculumLessonContent("Die Fahrkarte und das Gleis", "The ticket and the train platform", "dee FAHR-kar-teh / dahs glys", "Der Zug nach Hamburg fährt von Gleis vier ab.", "The train to Hamburg departs from platform four.", "Deutsche Bahn platforms are called 'Gleis'.")
                "Restaurants" -> CurriculumLessonContent("Die Rechnung, bitte", "The bill, please", "dee REKH-noong, BIT-teh", "Wir möchten zahlen, zusammen bitte.", "We would like to pay, together please.", "'Zusammen' means together, 'getrennt' means split.")
                "Describing People" -> CurriculumLessonContent("Freundlich und hilfsbereit", "Friendly and helpful", "FROYNT-likh / HILFS-beh-ryt", "Mein neuer Kollege ist sehr freundlich und kompetent.", "My new colleague is very friendly and competent.", "Predicate adjectives after 'sein' take no ending.")
                else -> CurriculumLessonContent("Schönes Wetter heute, oder?", "Nice weather today, isn't it?", "SHOEN-es VET-ter", "Heute scheint die Sonne und es ist angenehm warm.", "Today the sun is shining and it is pleasantly warm.", "Talking about weather is universally popular in Germany.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Darf ich kurz unterbrechen?", "May I briefly interrupt?", "darf ikh koorts", "Darf ich kurz nachfragen, wie Sie das meinen?", "May I briefly clarify what you mean by that?", "Polite modal verb 'dürfen' in subjunctive/polite form.")
                "Opinions" -> CurriculumLessonContent("Meiner Meinung nach", "In my opinion", "MY-ner MY-noong nakh", "Meiner Ansicht nach ist das eine hervorragende Idee.", "In my view, that is an outstanding idea.", "'Meiner Meinung nach' triggers inverted word order.")
                "Experiences" -> CurriculumLessonContent("Ich habe schon viel erlebt", "I have already experienced a lot", "ikh HAH-beh shohn", "Während meines Auslandsjahres habe ich viel gelernt.", "During my year abroad I learned a great deal.", "Genitive preposition 'während' is used in formal speech.")
                "Comparisons" -> CurriculumLessonContent("Größer als / Genauso wie", "Bigger than / Just as ... as", "GROE-ser ahls / geh-NOW-zoh vee", "Dieser Vorschlag ist viel überzeugender als der alte.", "This proposal is much more convincing than the old one.", "'als' is used with comparatives, 'wie' with equality.")
                "More Complex Grammar" -> CurriculumLessonContent("Konditionalsatz mit Wenn", "Conditional clause with If", "kon-dee-tsyo-NAHL-zats", "Wenn ich mehr Zeit hätte, würde ich mehr reisen.", "If I had more time, I would travel more.", "Konjunktiv II expresses hypothetical situations.")
                else -> CurriculumLessonContent("Hörverständnis im Alltag", "Listening comprehension in daily life", "HOER-fer-shtent-nis", "Ich habe den Podcast über Nachhaltigkeit gehört.", "I listened to the podcast on sustainability.", "Focus on compound words and fast sentence rhythm.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("Es war einmal vor langer Zeit", "Once upon a time long ago", "es vahr eyn-MAHL", "Plötzlich hörte er ein seltsames Geräusch im Wald.", "Suddenly he heard a strange sound in the forest.", "Narrative past (Präteritum) is standard in storytelling.")
                "Workplace Conversations" -> CurriculumLessonContent("Die Besprechung und der Bericht", "The meeting and the report", "beh-SHPREKH-oong", "Lassen Sie uns die Quartalszahlen gemeinsam analysieren.", "Let us analyze the quarterly figures together.", "Professional German values precision and punctuality.")
                "Social Situations" -> CurriculumLessonContent("Darf ich Ihnen vorstellen...", "May I introduce to you...", "darf ikh EE-nen", "Darf ich Ihnen meine geschätzte Kollegin vorstellen?", "May I introduce my esteemed colleague to you?", "Formal introductions follow polite social protocol.")
                "News & Media" -> CurriculumLessonContent("Die Schlagzeilen des Tages", "The headlines of the day", "SHLAHK-tsy-len", "Die Tageszeitung berichtet über wirtschaftliche Reformen.", "The daily newspaper reports on economic reforms.", "Passive voice is heavily used in German news reporting.")
                "Idiomatic Expressions" -> CurriculumLessonContent("Ich verstehe nur Bahnhof", "It's all Greek to me", "ikh fer-SHTAY-eh noor BAHN-hohf", "Er hat so schnell gesprochen, ich verstand nur Bahnhof.", "He spoke so fast, I didn't understand a thing.", "Famous German idiom meaning complete confusion.")
                else -> CurriculumLessonContent("Nebensätze mit Weil und Dass", "Subordinate clauses with Because and That", "NAY-ben-zet-seh", "Ich freue mich sehr, dass Sie heute gekommen sind.", "I am very pleased that you came today.", "In subordinate clauses, conjugated verbs move to the end.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Die gesellschaftlichen Auswirkungen", "The societal implications", "ows-VEER-koong-en", "Wir müssen die langfristigen Konsequenzen bedenken.", "We must consider the long-term consequences.", "Complex noun compounds convey precise technical meaning.")
                "Debate & Opinions" -> CurriculumLessonContent("Ich teile diesen Standpunkt nicht", "I do not share this viewpoint", "ikh TY-leh DEE-zen", "Da muss ich Ihnen respektvoll widersprechen.", "There I must respectfully disagree with you.", "Dative case follows the verb 'widersprechen'.")
                "Abstract Topics" -> CurriculumLessonContent("Ethik und technologischer Wandel", "Ethics and technological change", "AY-teek oont vahn-del", "Die Debatte über künstliche Intelligenz berührt ethische Grundfragen.", "The debate on artificial intelligence touches fundamental ethical questions.", "German philosophy has shaped modern conceptual discourse.")
                "Natural Expressions" -> CurriculumLessonContent("Den Nagel auf den Kopf treffen", "Hit the nail on the head", "dayn NAH-gel owf dayn kopf", "Mit dieser Bemerkung hast du den Nagel auf den Kopf getroffen.", "With that remark you hit the nail right on the head.", "Used when someone summarizes something perfectly.")
                "Listening Comprehension" -> CurriculumLessonContent("Wissenschaftliche Vorträge", "Scientific keynote lectures", "VOR-tray-geh", "Sie konnte den Argumenten des Referenten mühelos folgen.", "She was able to follow the speaker's arguments effortlessly.", "Listening for connecting particles like 'dennoch' and 'folglich'.")
                else -> CurriculumLessonContent("Argumentative Erörterung", "Structured argumentative essay", "er-OER-teh-roong", "Die Einleitung führt prägnant in das Thema ein.", "The introduction concisely leads into the subject.", "A classic German academic essay structure.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Sorgfältige Abwägung", "Careful deliberation and weighing", "AHB-vay-goong", "Es bedarf einer gründlichen Analyse aller Faktoren.", "A thorough analysis of all factors is required.", "High-register genitive construction 'bedarf + Genitiv'.")
                "Cultural Context" -> CurriculumLessonContent("Weimarer Klassik und Romantik", "Weimar classicism and romanticism", "VY-mah-rer KLAH-sik", "Goethe und Schiller prägten die deutsche Dichtkunst maßgeblich.", "Goethe and Schiller decisively shaped German literature.", "Cultural mastery provides depth to conversation.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Feinsinnig und vielschichtig", "Subtle and multi-layered", "FYN-zin-nikh / FEEL-shikh-tikh", "Ihre Argumentation war bemerkenswert vielschichtig.", "Her line of reasoning was remarkably multi-layered.", "Elevated adjectives enrich formal speech.")
                "Advanced Listening" -> CurriculumLessonContent("Podiumsdiskussion mit Dialekten", "Panel discussion with regional accents", "POH-dyooms-dis-koos-yohn", "Er verstand selbst die schwäbischen und bayerischen Nuancen.", "He understood even the Swabian and Bavarian nuances.", "Regional accents are common across German-speaking media.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("Höflichkeitsformel vs Umgangssprache", "Formal etiquette vs Colloquial register", "HOEF-likh-kyts-for-mel", "Sehr geehrte Damen und Herren gegenüber Hallo zusammen.", "Esteemed Ladies and Gentlemen versus Hello everyone.", "Navigating social distance with precision.")
                else -> CurriculumLessonContent("Passivformen mit Modalverben", "Passive voice with modal auxiliaries", "PAH-seef-for-men", "Dieser Vertrag muss unverzüglich unterzeichnet werden.", "This contract must be signed without delay.", "Essential for bureaucratic and legal German.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Strategische Verhandlungsführung", "Strategic negotiation management", "fer-HAHND-loongs-foo-roong", "Wir haben ein bilaterales Kooperationsabkommen erzielt.", "We achieved a bilateral cooperation agreement.", "Executive business and diplomatic language.")
                "Advanced Reading" -> CurriculumLessonContent("Thomas Mann und Franz Kafka", "Thomas Mann and Franz Kafka literary texts", "KAHF-kah", "Kafkas Werke reflektieren existentielle Fragestellungen.", "Kafka's works reflect existential questions.", "Deep literary appreciation in the original German.")
                "Idioms & Expressions" -> CurriculumLessonContent("Die Kirche im Dorf lassen", "Don't get carried away / Keep things grounded", "dee KEER-kheh im dorf", "Lassen wir bei den Planungen doch bitte die Kirche im Dorf.", "Let us please stay grounded in our project planning.", "Historic German idiom advising moderation.")
                "Advanced Writing" -> CurriculumLessonContent("Wissenschaftliche Publikation", "Academic publication and thesis", "poo-blee-kah-TSYOHN", "Die empirische Untersuchung liefert belastbare Ergebnisse.", "The empirical study provides robust results.", "Scholarly precision in German academic writing.")
                "Difficult Listening" -> CurriculumLessonContent("Parlamentsdebatte im Bundestag", "Parliamentary debate in the Bundestag", "BOON-des-tahk", "Sie erfasste alle Zwischenrufe und rhetorischen Wendungen.", "She caught all heckles and rhetorical devices.", "Comprehending fast political discourse live.")
                else -> CurriculumLessonContent("Muttersprachliche Ausdruckskraft", "Native expressive power", "MOOT-ter-sprahkh-likh", "Er artikuliert komplexe Sachverhalte mühelos und stilsicher.", "He articulates complex matters effortlessly and stylistically confident.", "Bilingual near-native fluency.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("Mühelose Sprachgewandtheit", "Effortless eloquence", "SPRAHKH-geh-vahnt-hyt", "Das Gespräch verlief mit bemerkenswerter Natürlichkeit.", "The conversation proceeded with remarkable naturalness.", "Fluent cadence without hesitation.")
                "Humor & Cultural References" -> CurriculumLessonContent("Hintersinniger Humor und Wortwitz", "Subtle dry humor and wordplay", "HIN-ter-zin-nee-ger", "Sie verstand den feinsinnigen Kabarett-Humor auf Anhieb.", "She understood the subtle satirical cabaret humor instantly.", "Cabaret and satire require deep cultural awareness.")
                "Advanced Debates" -> CurriculumLessonContent("Rhetorische Meisterklasse", "Rhetorical masterclass", "reh-TOH-ree-sheh", "Sie überzeugte das gesamte Auditorium mit schlagkräftiger Logik.", "She convinced the entire auditorium with compelling logic.", "Commanding oratory in public forums.")
                "Professional Fluency" -> CurriculumLessonContent("Führungskompetenz im DACH-Raum", "Executive leadership in the DACH region", "FOO-roongs-kom-peh-tents", "Er leitete die internationale Aufsichtsratssitzung in Frankfurt.", "He chaired the international supervisory board meeting in Frankfurt.", "Corporate leadership in Germany, Austria, and Switzerland.")
                "Native-Speed Listening" -> CurriculumLessonContent("Akustische Spontanerfassung", "Instant auditory processing", "ah-KOOS-tish", "Selbst bei raschem Sprechtempo ging kein Wort verloren.", "Even at rapid speaking speed, not a single word was lost.", "Total auditory mastery.")
                else -> CurriculumLessonContent("Vollständige kulturelle Immersion", "Complete cultural immersion", "eem-mehr-ZYOHN", "Leben und Arbeiten in Deutschland mit heimatlicher Selbstverständlichkeit.", "Living and working in Germany with instinctive naturalness.", "True bilingual and bicultural mastery.")
            }
        }
    }
}

object ItalianCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Buongiorno / Buonasera", "Good morning / Good evening", "bwon-JYOHR-noh / bwoh-nah-SEH-rah", "Buongiorno! Come sta oggi?", "Good morning! How are you today? (formal)", "'Ciao' is for friends, 'Buongiorno' is formal and polite.")
                "Introducing Yourself" -> CurriculumLessonContent("Mi chiamo...", "My name is...", "mee KYAH-moh", "Mi chiamo Marco e vengo da Roma.", "My name is Marco and I come from Rome.", "Literally 'I call myself'. Italian verbs show person.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Sì / No / Per favore / Grazie", "Yes / No / Please / Thank you", "see / noh / pehr fah-VOH-reh / GRAHT-syeh", "Sì, per favore! Molte grazie per l'aiuto.", "Yes, please! Many thanks for the help.", "'Prego' is the standard polite reply to 'Grazie'.")
                "Numbers 1–10" -> CurriculumLessonContent("Uno, due, tre...", "1 to 10 numerals", "OO-noh, DOO-eh, tray", "Due cappuccini e un cornetto, per favore.", "Two cappuccinos and a croissant, please.", "Essential for ordering at the Italian coffee bar.")
                "Basic Pronouns" -> CurriculumLessonContent("Io, tu, lui, lei, noi, voi, loro", "I, you, he, she, we, you all, they", "EE-oh, too, lwee, lay, noy, voy, LOH-roh", "Noi studiamo la lingua italiana insieme.", "We are studying the Italian language together.", "Subject pronouns are often dropped because verb endings are clear.")
                else -> CurriculumLessonContent("Scusa e Arrivederci", "Excuse me and Goodbye", "SKOO-zah / ah-ree-veh-DEHR-chee", "Scusi, dov'è la stazione ferroviaria?", "Excuse me, where is the railway station?", "Use 'Scusa' with peers and 'Scusi' formally.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("La famiglia", "The family", "lah fah-MEE-lyah", "Mio fratello e mia sorella vivono a Milano.", "My brother and my sister live in Milan.", "Family terms in singular drop the definite article: 'mio padre'.")
                "Colors" -> CurriculumLessonContent("Rosso, Blu, Giallo, Verde", "Red, Blue, Yellow, Green", "ROHS-soh, bloo, JAHL-loh, VEHR-deh", "La maglietta verde è molto elegante.", "The green shirt is very elegant.", "Colors agree in gender and number with the noun.")
                "Food" -> CurriculumLessonContent("La pasta e la pizza", "Pasta and pizza", "lah PAH-stah / lah PEET-tsah", "Adoro la pasta al dente con pomodoro fresco.", "I love al dente pasta with fresh tomato sauce.", "'Al dente' means cooked to be firm to the bite.")
                "Days & Months" -> CurriculumLessonContent("Lunedì a Domenica", "Monday to Sunday", "loo-neh-DEE ah doh-MEH-nee-kah", "Sabato sera andiamo in pizzeria.", "Saturday evening we are going to a pizzeria.", "Days of the week are not capitalized in Italian.")
                "Simple Questions" -> CurriculumLessonContent("Chi? Che cosa? Dove? Perché?", "Who? What? Where? Why?", "kee, kay KOH-zah, DOH-veh, pehr-KAY", "Perché hai scelto di visitare l'Italia?", "Why did you choose to visit Italy?", "Notice 'chi' means who, while 'che' means what.")
                else -> CurriculumLessonContent("Essere e Avere", "To be and To have", "EHS-seh-reh / ah-VEH-reh", "Sono pronto e ho molta fame.", "I am ready and I am very hungry.", "'Avere fame' (to have hunger) is used instead of to be hungry.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("La sveglia e la colazione", "Waking up and breakfast", "lah ZVEL-lyah", "Mi sveglio presto ogni mattina per fare colazione.", "I wake up early every morning to have breakfast.", "Reflexive verbs use pronouns 'mi, ti, si, ci, vi, si'.")
                "Shopping" -> CurriculumLessonContent("Quanto costa questo?", "How much does this cost?", "KWAHN-toh KOH-stah KWEH-stoh", "Quanto costa questo bellissimo vestito di lino?", "How much does this beautiful linen dress cost?", "Handy phrase in open-air markets and boutiques.")
                "Time" -> CurriculumLessonContent("Che ora è? / Che ore sono?", "What time is it?", "kay OH-rah ay / kay OH-reh SOH-noh", "Sono le tre e mezzo del pomeriggio.", "It is three thirty in the afternoon.", "Use 'È l'una' for one o'clock, and 'Sono le...' for all others.")
                "Directions" -> CurriculumLessonContent("Gira a destra e vai dritto", "Turn right and go straight", "JEE-rah ah DEH-strah", "Vai sempre dritto e poi gira a sinistra.", "Go straight ahead and then turn left.", "'A destra' is right, 'a sinistra' is left.")
                "Simple Sentences" -> CurriculumLessonContent("Vorrei prenotare un tavolo", "I would like to book a table", "vor-RAY preh-noh-TAH-reh", "Vorrei un tavolo all'aperto per due persone.", "I would like an outdoor table for two people.", "'Vorrei' is the polite conditional of 'volere'.")
                else -> CurriculumLessonContent("Come stai? Tutto bene?", "How are you? Everything good?", "KOH-meh sty / TOOT-toh BEH-neh", "Tutto bene, grazie! Che novità ci sono?", "Everything's good, thanks! What's new?", "'Tutto a posto' is another popular casual check-in.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Ieri ho visitato il museo", "Yesterday I visited the museum", "YEH-ree oh vee-zee-TAH-toh", "Ieri siamo andati a vedere il Colosseo a Roma.", "Yesterday we went to see the Colosseum in Rome.", "Passato prossimo uses avere or essere as auxiliary.")
                "Future Plans" -> CurriculumLessonContent("L'anno prossimo viaggerò", "Next year I will travel", "vyahd-jeh-ROH", "Quest'estate farò una vacanza in Toscana.", "This summer I will take a vacation in Tuscany.", "Futuro semplice endings are attached to the verb root.")
                "Travel" -> CurriculumLessonContent("Il biglietto del treno", "The train ticket", "bee-LYEHT-toh", "Un biglietto di andata e ritorno per Firenze.", "A round-trip ticket to Florence, please.", "'Andata e ritorno' signifies round-trip.")
                "Restaurants" -> CurriculumLessonContent("Il conto, per favore", "The bill, please", "eel KOHN-toh", "Era tutto delizioso, ci porta il conto per favore?", "Everything was delicious, could you bring the bill please?", "'Coperto' on the bill refers to bread and service.")
                "Describing People" -> CurriculumLessonContent("Simpatico, gentile e cordiale", "Friendly, kind, and warm", "seem-PAH-tee-koh", "La nostra guida turistica era cordiale e simpatica.", "Our tour guide was warm and friendly.", "Adjectives ending in -e serve both masculine and feminine.")
                else -> CurriculumLessonContent("Che bella giornata di sole!", "What a beautiful sunny day!", "kay BEL-lah zhyohr-NAH-tah", "Il clima in primavera è assolutamente ideale.", "The weather in spring is absolutely ideal.", "Weather is an effortless Italian conversation starter.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Posso esprimere il mio parere?", "May I express my viewpoint?", "pah-REH-reh", "Posso aggiungere una riflessione a riguardo?", "May I add a reflection regarding this?", "Nuanced conversational participation.")
                "Opinions" -> CurriculumLessonContent("Secondo il mio punto di vista", "According to my point of view", "seh-KOHN-doh", "Secondo me, l'arte rinascimentale è senza tempo.", "In my view, Renaissance art is timeless.", "'Secondo me' introduces personal evaluations smoothly.")
                "Experiences" -> CurriculumLessonContent("Un'esperienza memorabile", "A memorable experience", "meh-moh-RAH-bee-leh", "Vivere a Venezia è stata un'esperienza indimenticabile.", "Living in Venice was an unforgettable experience.", "Reflecting on travel and life moments.")
                "Comparisons" -> CurriculumLessonContent("Più bello di / Meno caro di", "More beautiful than / Less expensive than", "pyoo BEL-loh dee", "Questa piazza è molto più suggestiva dell'altra.", "This piazza is much more charming than the other.", "Use 'di' for comparisons between two nouns.")
                "More Complex Grammar" -> CurriculumLessonContent("L'imperfetto per le abitudini", "The imperfect tense for past habits", "eem-pehr-FET-toh", "Quando ero piccolo, trascorrevo l'estate al mare.", "When I was little, I used to spend summer by the sea.", "Imperfetto conveys ongoing or habitual past actions.")
                else -> CurriculumLessonContent("Ascolto di interviste radiofoniche", "Listening to radio interviews", "ah-SKOHL-toh", "Ho ascoltato un interessante programma su Radio 3.", "I listened to an interesting program on Radio 3.", "Train the ear to rapid melodic Italian intonation.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("C'era una volta in un antico borgo", "Once upon a time in an ancient village", "CHEH-rah OO-nah VOHL-tah", "All'improvviso, una melodia ruppe il silenzio della notte.", "Suddenly, a melody broke the silence of the night.", "Italian storytelling contrasts imperfetto and passato remoto.")
                "Workplace Conversations" -> CurriculumLessonContent("La riunione aziendale", "The corporate meeting", "ree-oo-NYOH-neh", "Dobbiamo definire le priorità strategiche del trimestre.", "We need to define the strategic priorities for the quarter.", "Corporate Italian is polite yet collaborative.")
                "Social Situations" -> CurriculumLessonContent("Un invito a cena tra amici", "A dinner invitation among friends", "een-VEE-toh", "Grazie di cuore per la splendida ospitalità.", "Heartfelt thanks for the splendid hospitality.", "Bringing a gift (like wine or dessert) is customary etiquette.")
                "News & Media" -> CurriculumLessonContent("La prima pagina del giornale", "The front page of the newspaper", "JYOHR-nah-leh", "La rassegna stampa commenta le nuove riforme.", "The press review comments on the new reforms.", "Reading editorial columns in Corriere della Sera.")
                "Idiomatic Expressions" -> CurriculumLessonContent("In bocca al lupo! — Crepi il lupo!", "Good luck! — May the wolf die!", "een BOHK-kah ahl LOO-poh", "Domani hai l'esame? In bocca al lupo!", "Tomorrow is your exam? Good luck!", "The classic Italian way to wish good luck; never say 'buona fortuna'.")
                else -> CurriculumLessonContent("Il congiuntivo presente", "The present subjunctive", "kohn-zhoon-TEE-voh", "Credo che sia la decisione più saggia per tutti.", "I believe that this is the wisest decision for everyone.", "Verbs of opinion and doubt trigger the subjunctive.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Le sfide culturali e sociali", "Cultural and social challenges", "SFEH-deh", "Occorre approfondire le radici di questo fenomeno.", "It is necessary to delve into the roots of this phenomenon.", "Formal analytical Italian.")
                "Debate & Opinions" -> CurriculumLessonContent("Dissento con dovuto rispetto", "I disagree with due respect", "dees-SEHN-toh", "Condivido le premesse, ma non la conclusione.", "I share the premises, but not the conclusion.", "Cultured debate with diplomatic politeness.")
                "Abstract Topics" -> CurriculumLessonContent("Filosofia, etica ed estetica", "Philosophy, ethics, and aesthetics", "eh-STEH-tee-kah", "Il dibattito sul legame tra bellezza e verità morale.", "The debate on the link between beauty and moral truth.", "Italian renaissance philosophy and humanism.")
                "Natural Expressions" -> CurriculumLessonContent("Non avere peli sulla lingua", "To speak one's mind plainly", "PAY-lee SOOL-lah LEEN-gwah", "Ha detto esattamente ciò che pensava, senza peli sulla lingua.", "She said exactly what she thought, completely outspoken.", "Means speaking candidly and without inhibition.")
                "Listening Comprehension" -> CurriculumLessonContent("Dibattito parlamentare e accademico", "Parliamentary and academic debate", "pah-droh-NAHN-zah", "Seguire il ritmo incalzante degli oratori senza pause.", "Following the fast-paced tempo of the speakers without pauses.", "Mastery of rapid spoken dialogue and colloquial fillers.")
                else -> CurriculumLessonContent("Saggio critico e argomentazione", "Critical essay and argumentation", "SAHD-jyoh", "Un'analisi approfondita condotta con rigore filologico.", "An in-depth analysis conducted with philological rigor.", "High Italian academic composition.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Articolare concetti sofisticati", "Articulating sophisticated concepts", "ahr-tee-koh-LAH-reh", "Ha sintetizzato gli argomenti con rara lucidità.", "He synthesized the arguments with rare lucidity.", "Expressing intricate ideas with clarity.")
                "Cultural Context" -> CurriculumLessonContent("Dante, Petrarca e l'eredità classica", "Dante, Petrarch, and classical heritage", "DAHN-teh", "La Divina Commedia ha plasmato l'identità linguistica italiana.", "The Divine Comedy shaped Italian linguistic identity.", "Italian literature as the bedrock of cultural eloquence.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Effimero, sublime e suggestivo", "Ephemeral, sublime, and suggestive", "ehf-FEE-meh-roh", "La luce del crepuscolo sulle colline era sublime.", "The twilight light over the hills was sublime.", "Rich poetic and evocative adjectives.")
                "Advanced Listening" -> CurriculumLessonContent("Conferenza magistrale e dialetti", "Masterclass lecture and regional accents", "kohn-feh-REHN-tsah", "Cogliere le cadenze toscane, romane e napoletane.", "Catching Tuscan, Roman, and Neapolitan inflections.", "Distinguishing regional accents with ease.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("L'uso del Lei formale e del Tu", "Using formal 'Lei' versus informal 'Tu'", "lay / too", "Le sarei immensamente grato se potesse valutare l'offerta.", "I would be immensely grateful if you could evaluate the offer.", "The formal 'Lei' takes the third person singular.")
                else -> CurriculumLessonContent("Periodo ipotetico dell'irrealtà", "Hypothetical clauses of impossibility", "peh-REE-oh-doh", "Se l'avessi saputo prima, sarei venuto subito.", "If I had known earlier, I would have come immediately.", "Congiuntivo trapassato paired with condizionale passato.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Negoziati di alta finanza e diplomazia", "High finance and diplomatic negotiations", "neh-goh-TSYAH-tee", "Le parti hanno sottoscritto un protocollo d'intesa congiunto.", "The parties signed a joint memorandum of understanding.", "Executive corporate and legal Italian.")
                "Advanced Reading" -> CurriculumLessonContent("Italo Calvino e Umberto Eco", "Italo Calvino and Umberto Eco literature", "kahl-VEE-noh / EH-koh", "L'opera esplora i confini tra semiotica e narrazione.", "The work explores boundaries between semiotics and storytelling.", "Appreciating complex literary prose.")
                "Idioms & Expressions" -> CurriculumLessonContent("Piovere sul bagnato", "When it rains it pours / Misfortunes compound", "PYOH-veh-reh sool bahn-YAH-toh", "Dopo il ritardo si è rotto il motore: piove sul bagnato!", "After the delay the engine broke: when it rains it pours!", "Traditional picturesque Italian idiom.")
                "Advanced Writing" -> CurriculumLessonContent("Trattato saggistico ed editoriale", "Scholarly treatise and editorial", "trat-TAH-toh", "Una riflessione saggistica che illumina la modernità.", "An essayistic reflection that illuminates modernity.", "Polished, publishable Italian prose.")
                "Difficult Listening" -> CurriculumLessonContent("Rappresentazione teatrale di Pirandello", "Theatrical play by Pirandello", "pee-rahn-DEL-loh", "Decifrare il gioco dialettico tra finzione e realtà scenica.", "Deciphering the dialectic between fiction and stage reality.", "Supreme auditory comprehension.")
                else -> CurriculumLessonContent("Padronanza quasi madrelingua", "Near-native linguistic mastery", "pah-droh-NAHN-zah", "Esprimersi con naturalezza, eleganza e profonda precisione.", "Expressing oneself with ease, elegance, and deep precision.", "Effortless bilingual fluency.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("Fluente disinvoltura verbale", "Fluent verbal poise and natural cadence", "dee-zeen-vohl-TOO-rah", "La conversazione fluisce con assoluta spontaneità e grazia.", "The conversation flows with absolute spontaneity and grace.", "Native cadence and conversational charm.")
                "Humor & Cultural References" -> CurriculumLessonContent("Ironia sottile e commedia all'italiana", "Subtle irony and Italian comedy", "ee-roh-NEE-ah", "Cogliere il sarcasmo bonario e il doppio senso culturale.", "Catching good-natured sarcasm and cultural double meanings.", "Mastering culturally anchored humor.")
                "Advanced Debates" -> CurriculumLessonContent("Oratoria e persuasione", "Oratory and persuasion", "oh-rah-TOH-ryah", "Difendere una tesi con argomentazioni impeccabili.", "Defending a thesis with impeccable arguments.", "Commanding rhetoric in intellectual circles.")
                "Professional Fluency" -> CurriculumLessonContent("Leadership nel Made in Italy", "Executive leadership in Made in Italy", "lee-dehr-SHEEP", "Dirigere con autorevolezza incontri istituzionali di vertice.", "Leading high-level institutional summits with authority.", "Excellence in Italian design, fashion, and industry.")
                "Native-Speed Listening" -> CurriculumLessonContent("Comprensione aurale istantanea", "Instant auditory comprehension", "kohm-prehn-ZYOH-neh", "Percepire ogni minima sfumatura fonetica in tempo reale.", "Perceiving every subtle phonetic nuance in real time.", "Full acoustic mastery.")
                else -> CurriculumLessonContent("Immersione totale e bilinguismo", "Total immersion and bilingualism", "eem-mehr-ZYOHN", "Vivere, pensare e sognare in lingua italiana.", "Living, thinking, and dreaming in the Italian language.", "Complete linguistic and cultural integration.")
            }
        }
    }
}
